from math import gcd


def gcd_list(numbers):
    result = 0
    for n in numbers:
        result = gcd(result, abs(n))
    return result


def lcm_list(numbers):
    if not numbers:
        return 1
    result = 1
    for n in numbers:
        n = abs(n)
        if n == 0:
            return 0
        result = result // gcd(result, n) * n
    return result

