def parse_log_line(line):
    result = {}
    for token in line.split():
        if '=' not in token:
            raise ValueError(f'Invalid token: {token!r}')
        key, value = token.split('=', 1)
        if not key:
            raise ValueError(f'Invalid key in token: {token!r}')
        result[key] = value
    return result

