import unittest

import matrix


class TestMatrix(unittest.TestCase):
    def test_add_normal(self):
        a = [[1, 2], [3, 4]]
        b = [[5, 6], [7, 8]]
        self.assertEqual(matrix.add(a, b), [[6, 8], [10, 12]])

    def test_add_1x1(self):
        self.assertEqual(matrix.add([[1]], [[2]]), [[3]])

    def test_add_dimension_mismatch(self):
        with self.assertRaises(ValueError):
            matrix.add([[1, 2]], [[1]])

    def test_transpose_normal(self):
        self.assertEqual(
            matrix.transpose([[1, 2, 3], [4, 5, 6]]),
            [[1, 4], [2, 5], [3, 6]],
        )

    def test_transpose_empty(self):
        self.assertEqual(matrix.transpose([]), [])

    def test_transpose_1x1(self):
        self.assertEqual(matrix.transpose([[7]]), [[7]])

    def test_det_1x1(self):
        self.assertAlmostEqual(matrix.det([[5]]), 5.0)

    def test_det_2x2(self):
        self.assertAlmostEqual(matrix.det([[1, 2], [3, 4]]), -2.0)

    def test_det_3x3_identity(self):
        self.assertAlmostEqual(
            matrix.det([[1, 0, 0], [0, 1, 0], [0, 0, 1]]),
            1.0,
        )

    def test_det_singular(self):
        self.assertAlmostEqual(matrix.det([[1, 2], [2, 4]]), 0.0)

    def test_det_empty(self):
        self.assertAlmostEqual(matrix.det([]), 1.0)

    def test_det_non_square(self):
        with self.assertRaises(ValueError):
            matrix.det([[1, 2, 3], [4, 5, 6]])


if __name__ == '__main__':
    unittest.main()

