import unittest
import ntpath
from config_loader import build_windows_path

class TestConfigLoader(unittest.TestCase):
    def test_normal_join(self):
        self.assertEqual(build_windows_path('C:\\Users\\Test', 'config.ini'),
                         ntpath.join('C:\\Users\\Test', 'config.ini'))

    def test_trailing_backslash(self):
        self.assertEqual(build_windows_path('C:\\Users\\Test\\', 'config.ini'),
                         ntpath.join('C:\\Users\\Test\\', 'config.ini'))

    def test_absolute_filename(self):
        self.assertEqual(build_windows_path('C:\\Users\\Test', 'D:\\other\\config.ini'),
                         ntpath.join('C:\\Users\\Test', 'D:\\other\\config.ini'))

    def test_rooted_filename(self):
        self.assertEqual(build_windows_path('C:\\Users\\Test', '\\config.ini'),
                         ntpath.join('C:\\Users\\Test', '\\config.ini'))

    def test_empty_filename(self):
        self.assertEqual(build_windows_path('C:\\Users\\Test', ''),
                         ntpath.join('C:\\Users\\Test', ''))

    def test_empty_base(self):
        self.assertEqual(build_windows_path('', 'config.ini'),
                         ntpath.join('', 'config.ini'))

if __name__ == '__main__':
    unittest.main()

